#!/usr/bin/env node
// Static checks for the site: local links and assets exist, anchors have targets, there is one h1, images have alt
// text, the generated byte view is present, og.png is a 1280x640 PNG under 1 MB. Zero dependencies.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SITE = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const problems = [];
const html = fs.readFileSync(path.join(SITE, 'index.html'), 'utf8');

for (const [, attr, url] of html.matchAll(/\b(href|src)="([^"]+)"/g)) {
  if (/^(https?:|data:|mailto:|#)/.test(url)) continue;
  if (!fs.existsSync(path.join(SITE, url.split(/[?#]/)[0]))) problems.push(`${attr}="${url}" points to a missing file`);
}
for (const [, id] of html.matchAll(/href="#([^"]+)"/g)) if (id && !html.includes(`id="${id}"`)) problems.push(`#${id} has no target`);
if (!/<!-- hex:start[\s\S]*class="hx"[\s\S]*<!-- hex:end -->/.test(html)) problems.push('the byte view is missing; run node site/demo/record.mjs');
if ((html.match(/<h1\b/g) ?? []).length !== 1) problems.push('the page needs exactly one h1');
for (const [, tag] of html.matchAll(/<img\b([^>]*)>/g)) if (!/\balt="[^"]*"/.test(tag)) problems.push(`an image has no alt attribute: ${tag.trim().slice(0, 60)}`);

const png = fs.readFileSync(path.join(SITE, 'og.png'));
const [w, h] = [png.readUInt32BE(16), png.readUInt32BE(20)];
if (png.subarray(0, 8).toString('hex') !== '89504e470d0a1a0a' || w !== 1280 || h !== 640) problems.push(`og.png must be a 1280x640 PNG (is ${w}x${h})`);
if (png.length > 1024 * 1024) problems.push('og.png must stay under 1 MB for GitHub social previews');

if (problems.length) { for (const p of problems) console.error(`site: ${p}`); process.exit(1); }
console.log('site: links, anchors, images, byte view and og.png are fine');
